    61  void *af_get_null_terminated(const uint8_t **data, size_t *size) {
    62  #define STR_SIZE 75
    63    if (*size < STR_SIZE || (int)*size < 0) {
    64      return NULL;
    65    }
    66
    67    void *new_s = malloc(STR_SIZE + 1);
    68    memcpy(new_s, *data, STR_SIZE);
    69    ((uint8_t *)new_s)[STR_SIZE] = '\0';
    70
    71    *data = *data+STR_SIZE;
    72    *size -= STR_SIZE;
    73    return new_s;
    74  }
