    76  void *af_gb_get_random_data(const uint8_t **data, size_t *size, size_t to_get) {
    77    if (*size < to_get || (int)*size < 0) {
    78      return NULL;
    79    }
    80
    81    void *new_s = malloc(to_get);
    82    memcpy(new_s, *data, to_get);
    83
    84    pointer_arr[pointer_idx++] = new_s;
    85
    86    *data = *data + to_get;
    87    *size -= to_get;
    88
    89    return new_s;
    90  }
