    92  void *af_gb_get_null_terminated(const uint8_t **data, size_t *size) {
    93
    94    void *nstr = af_get_null_terminated(data, size);
    95    if (nstr == NULL) {
    96      return NULL;
    97    }
    98    pointer_arr[pointer_idx++] = nstr;
    99    return nstr;
