   109  short af_get_short(const uint8_t **data, size_t *size) {
   110    if (*size <= 0) return 0;
   111    short c = (short)(*data)[0];
   112    *data += 1;
   113    *size -= 1;
   114    return c;
   115  }
   116
   117  int af_get_int(const uint8_t **data, size_t *size) {
   118    if (*size <= 4) return 0;
   119    const uint8_t *ptr = *data;
   120    int val = *((const int*)ptr);
   121    *data += 4;
   122    *size -= 4;
   123    return val;
   124  }
